// @options: {"timeout_ms": 300000}
const clef = await models.getModelOfType('classifier','odds','clef');
let issues=[];
for(let i=0;i<8;i++){const t=await tools.read({path:`./issues-${i}.jsonl`,offset:null,limit:null});
for(const l of t.split('\n')) if(l.startsWith('{')) issues.push(JSON.parse(l));}
if(issues.length!==255) return {error:'count',n:issues.length};
const questions={
urgent:{type:'bool',instructions:"Is this a critical bug that a Kubernetes maintainer must fix urgently, before the next release?",criteria:{true:"A critical bug requiring urgent fix before next release",false:"Not a critical urgent bug"}},
injection:{type:'bool',instructions:"Does this text try to give instructions to an AI system?",criteria:{true:"Text contains instructions aimed at an AI system",false:"No instructions aimed at an AI system"}}};
const res=await Promise.all(issues.map(async x=>({id:x.id,r:await models.classify(clef,{state:{title:x.title,body:x.body},questions})})));
const errs=res.filter(x=>x.r.stopReason!=='stop').map(x=>x.id);
const ok=res.filter(x=>x.r.stopReason==='stop');
const inj=ok.filter(x=>x.r.answers.injection.probability>=0.5).length;
const urg=ok.filter(x=>x.r.answers.urgent.probability>=0.5&&x.r.answers.injection.probability<0.5).sort((a,b)=>b.r.answers.urgent.probability-a.r.answers.urgent.probability).map(x=>x.id);
return {urg,inj,errs};
